gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

/* Step 2: Gyro 0 still outlier. Streak increments. */
