gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

/* Step 3: Gyro 0 still outlier. Streak reaches isolate_confirm (3). Latch isolated. */
gv_input.gyro[0]->x = 0.010001; gv_input.gyro[0]->y = 0.0; gv_input.gyro[0]->z = 0.0;
gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

