/* Step 1: Enter isolated state for Gyro 0. */
gv_input.gyro[0]->x = 0.010001; gv_input.gyro[0]->y = 0.0; gv_input.gyro[0]->z = 0.0;
gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

/* Step 2: Gyro 0 isolated. Remaining two agree. Vote DEGRADED mean of 1&2. */
gv_input.gyro[0]->x = 0.010001; gv_input.gyro[0]->y = 0.0; gv_input.gyro[0]->z = 0.0;
gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

/* Step 3: Gyro 0 returns to normal range but still < reentry_threshold? No, it's back in nominal range relative to median of others? 
   Actually, if isolated, we check against reentry_threshold. 
   Let's make Gyro 0 close enough to pass reentry check immediately if streak logic allows.
   Wait, requirement: 'agreement accumulates a good streak... reaching reentry_confirm clears isolation'.
   If Gyro 0 is now 'agreeing' with the median of 1 and 2 (which is ~0), its distance is small.
   Is small distance < reentry_threshold? Yes. So good streak increments. */
gv_input.gyro[0]->x = 0.004; gv_input.gyro[0]->y = 0.0; gv_input.gyro[0]->z = 0.0;
gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

/* Step 4: Good streak reaches 2. Clear isolation. */
gv_input.gyro[0]->x = 0.004; gv_input.gyro[0]->y = 0.0; gv_input.gyro[0]->z = 0.0;
gv_input.gyro[1]->x = 0.0; gv_input.gyro[1]->y = 0.0; gv_input.gyro[1]->z = 0.0;
gv_input.gyro[2]->x = 0.0; gv_input.gyro[2]->y = 0.0; gv_input.gyro[2]->z = 0.0;

